const icon=(name)=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.layers}"/></svg>`;
let state=null,session=null,authError='',authBusy=false,authRemember=false,activation=null,activationToken=null,activationInvalid=false;
const initialFragment=new URLSearchParams(location.hash.slice(1));
if(initialFragment.has('activate')){activationToken=initialFragment.get('activate');initialFragment.delete('activate');history.replaceState(null,'',location.pathname+location.search);}
let pref;try{pref=JSON.parse(localStorage.getItem(PREF));}catch{}pref||={};
const ui={route:routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard',userId:null,companyId:pref.companyId||null,query:'',source:'all',priority:'all',status:'all',owner:'all',availability:'all',drawer:null,modal:null,feedFilter:'all',reportCompany:'current',reportSeller:'all',reportSource:'all',reportFrom:'',reportTo:'',dismissed:pref.dismissed||[],mobile:false};
let transient=[],lastFocus=null,drawerScroll=0;
const currentUser=()=>state.users.find(x=>x.id===ui.userId)||state.users[0];
const isChief=()=>currentUser().role==='hoofdbeheerder';
const canManage=()=>isChief()||currentUser().role==='bedrijfsbeheerder';
const company=()=>state.companies.find(x=>x.id===ui.companyId)||state.companies[0];
const activeUsers=()=>state.users.filter(u=>u.companyId===company().id&&u.status!=='uitgenodigd');
const userName=id=>state.users.find(x=>x.id===id)?.name||'Niet toegewezen';
const work=l=>getWorkspace(state,company().id,typeof l==='string'?l:l.id);
const companyName=id=>state.companies.find(c=>c.id===id)?.name||'Onbekend bedrijf';
const companyLogoSource=c=>typeof c?.logoUrl==='string'&&c.logoUrl.startsWith('/api/company-logos/')?c.logoUrl:null;
function companyLogoMarkup(c){const src=companyLogoSource(c);return src?`<span class="company-logo has-image"><img class="company-logo-image" src="${esc(src)}" alt="Logo van ${esc(c.name)}" loading="lazy"></span>`:`<span class="company-logo" style="background:${esc(c.color||'#dce8ff')}">${esc(c.initials||c.name.slice(0,2))}</span>`;}
function dashboardBrand(){const c=company(),src=companyLogoSource(c);return `<span class="brand-mark ${src?'has-company-logo':''}">${src?`<img class="dashboard-company-logo" src="${esc(src)}" alt="Logo van ${esc(c.name)}">`:icon('building')}</span><span>${esc(c.name)}<small>Dashboard</small></span>`;}
function companyEditorHTML(c){return modalShell('Bedrijf bewerken',`<form id="company-edit-form"><input type="hidden" name="companyId" value="${esc(c.id)}"><label class="field"><span>Bedrijfsnaam</span><input name="name" required maxlength="120" value="${esc(c.name)}" autocomplete="organization"></label><div class="company-logo-editor"><div class="company-logo-preview" aria-label="Voorbeeld bedrijfslogo"></div><div class="company-logo-controls"><label class="field"><span>Bedrijfslogo</span><input class="logo-file-input" type="file" accept="image/png,image/jpeg,image/webp" data-company-logo aria-describedby="logo-upload-note"></label><p class="logo-upload-note" id="logo-upload-note">PNG, JPG of WebP, maximaal 5 MB. We verkleinen het bestand automatisch.</p>${btn('Logo verwijderen','remove-company-logo','ghost small')}<p class="company-logo-status" aria-live="polite"></p></div></div><p class="muted help-text">Het logo verschijnt na het opslaan in het dashboard van de gebruikers van dit bedrijf.</p>${formButtons('Wijzigingen opslaan')}</form>`);}
function updateCompanyLogoPreview(){
 const m=ui.modal;if(m?.type!=='edit-company')return;
 const c=state.companies.find(item=>item.id===m.id),preview=$('.company-logo-preview'),status=$('.company-logo-status');
 if(preview)preview.innerHTML=m.logoDraft?`<img src="${esc(m.logoDraft)}" alt="Voorbeeld van het bedrijfslogo">`:`<span>${esc(c?.initials||'Logo')}</span>`;
 if(status){status.textContent=m.logoBusy?'Logo voorbereiden…':m.logoError||'';status.setAttribute('role',m.logoError?'alert':'status');}
 const submit=$('#company-edit-form [type=submit]');if(submit)submit.disabled=!!m.logoBusy;
 const remove=$('[data-action="remove-company-logo"]');if(remove)remove.disabled=!!m.logoBusy||!m.logoDraft;
 const file=$('[data-company-logo]');if(file)file.disabled=!!m.logoBusy;
}
async function prepareCompanyLogo(file){
 if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Kies een PNG-, JPG- of WebP-afbeelding.');
 if(file.size>5*1024*1024)throw Error('Kies een afbeelding van maximaal 5 MB.');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('De afbeelding kon niet worden gelezen.'));reader.readAsDataURL(file);});
 const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Deze afbeelding kan niet worden geopend. Kies een ander bestand.'));img.src=data;});
 if(!image.naturalWidth||!image.naturalHeight||image.naturalWidth>12000||image.naturalHeight>12000)throw Error('Kies een kleinere, geldige afbeelding.');
 let scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight));
 const canvas=document.createElement('canvas'),context=canvas.getContext('2d');if(!context)throw Error('Je browser kan dit logo niet voorbereiden.');
 for(let attempt=0;attempt<5;attempt++){
  canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);
  const png=canvas.toDataURL('image/png');if(png.length*3/4<=192*1024)return png;
  const webp=canvas.toDataURL('image/webp',0.9);if(webp.length*3/4<=192*1024)return webp;
  scale*=0.75;
 }
 throw Error('Het logo blijft te groot. Kies een kleinere afbeelding.');
}
const statusName=id=>company().columns.find(c=>c.id===id)?.name||'Nieuw';
function save(){try{localStorage.setItem(PREF,JSON.stringify({companyId:ui.companyId,dismissed:ui.dismissed}));}catch{}}
let mutationQueue=Promise.resolve(),pendingMutations=0,refreshVersion=0,lastSync=null;
async function api(path,{method='GET',body,publicRequest=false}={}){
 const headers={Accept:'application/json'};
 if(body!==undefined)headers['Content-Type']='application/json';
 if(session?.csrfToken&&method!=='GET')headers['X-CSRF-Token']=session.csrfToken;
 let response;try{response=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'});}catch{throw Error('Geen verbinding met de server. Probeer het opnieuw.');}
 const result=await response.json().catch(()=>({error:'De server gaf geen geldig antwoord.'}));
 if(!response.ok){if(response.status===401&&!publicRequest){session=null;state=null;refreshVersion++;ui.modal=null;ui.drawer=null;authError='Je sessie is verlopen. Log opnieuw in.';renderAuth();}throw Error(result.error||'De actie kon niet worden uitgevoerd.');}
 return result;
}
function applyServer(result){if(!session?.authenticated)throw Error('Je sessie is verlopen. Log opnieuw in.');state=result.state;ui.userId=result.userId;ui.companyId=result.companyId;lastSync=new Date();save();}
async function refreshState(companyId=ui.companyId,{renderPage=true,force=false}={}){
 if(!session?.authenticated||(!force&&pendingMutations))return;
 const version=++refreshVersion;
 const result=await api('/api/state'+(companyId?'?companyId='+encodeURIComponent(companyId):''));
 if(version!==refreshVersion||!session?.authenticated)return;
 applyServer(result);
 if(renderPage)render();else renderToasts();
 return result;
}
function mutate(type,payload={},targetCompany=ui.companyId){
 pendingMutations++;
 refreshVersion++;
 const job=mutationQueue.then(async()=>{
  const result=await api('/api/action',{method:'POST',body:{type,companyId:targetCompany,payload}});
  applyServer(result);
  return result;
 });
 mutationQueue=job.catch(()=>{});
 return job.finally(()=>{pendingMutations--;});
}
async function switchCompany(id){
 if(!isChief())throw Error('Je kunt alleen je eigen bedrijf openen.');
 await mutationQueue;ui.drawer=null;ui.modal=null;ui.reportSeller='all';resetFilters();await refreshState(id,{force:true});
}
function showInviteLink(result){
 const details=result.result||{};
 if(!details.token)throw Error('De uitnodiging is opgeslagen, maar de link ontbreekt. Maak een nieuwe link.');
 const inviteUrl=location.origin+'/#activate='+encodeURIComponent(details.token);
 openModal('invite-link',null,{inviteUrl,invitation:details.invitation});
}
function passwordField(name,label,activating){
 const inputId='auth-'+name;
 return `<div class="field"><label for="${inputId}">${esc(label)}</label><div class="password-field"><input id="${inputId}" name="${name}" type="password" required ${activating?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'} maxlength="200"><button type="button" class="button ghost password-toggle" data-action="toggle-password" aria-controls="${inputId}" aria-pressed="false" aria-label="${esc(label)} tonen">Tonen</button></div></div>`;
}
function authMarkup(){
 const activating=!!activationToken,invalid=activating&&activationInvalid;
 const intro='<main id="main" class="auth-shell" tabindex="-1"><section class="auth-intro"><div class="brand"><span class="brand-mark">'+icon('building')+'</span><span>Bouwberichten<small>Dashboard</small></span></div></section><section class="auth-card"><span class="badge blue">'+(activating?'Uitnodiging':'Jouw werkplek')+'</span><h1 class="auth-title">'+(activating?'Welkom bij het team':'Log in op je dashboard')+'</h1><p>'+(activating?'Activeer je account met deze persoonlijke uitnodiging.':'Gebruik het e-mailadres en wachtwoord van je geactiveerde account.')+'</p>'+(authError?'<div class="auth-error" role="alert">'+esc(authError)+'</div>':'');
 let content;
 if(invalid)content='<p>Vraag de beheerder om een nieuwe uitnodigingslink. Een link werkt één keer en heeft een vervaldatum.</p><button class="button secondary" data-action="show-login">Naar inloggen</button>';
 else if(activating&&!activation)content='<p role="status">Uitnodiging controleren…</p>';
 else content='<form id="'+(activating?'activation-form':'login-form')+'">'+(activating?'<div class="invitation-summary"><strong>'+esc(activation.companyName)+'</strong><span>'+esc(activation.role)+'</span><span>Geldig tot '+fmt(activation.expiresAt)+'</span></div><label class="field"><span>Je naam</span><input name="name" required maxlength="100" autocomplete="name" value="'+esc(activation.name)+'"></label>':'')+'<label class="field"><span>E-mailadres</span><input name="email" type="email" required maxlength="160" autocomplete="username" '+(activating?'readonly value="'+esc(activation.email)+'"':'')+'></label>'+passwordField('password',activating?'Kies een wachtwoord':'Wachtwoord',activating)+(activating?passwordField('passwordConfirm','Herhaal je wachtwoord',true)+'<p class="muted help-text">Gebruik minimaal 12 tekens. Je account is uitsluitend gekoppeld aan '+esc(activation.companyName)+'.</p>':'<label class="remember-login"><input name="rememberMe" type="checkbox" value="true" '+(authRemember?'checked':'')+'><span>Aangemeld blijven<small>30 dagen op dit apparaat</small></span></label><p class="muted help-text">Nog geen account of je wachtwoord vergeten? Vraag je beheerder om hulp.</p>')+'<button type="submit" class="button primary auth-submit" '+(authBusy?'disabled':'')+'>'+(authBusy?'Even geduld…':activating?'Account activeren':'Inloggen')+'</button></form>';
 return intro+content+'<div class="auth-bottom">'+icon('shield')+' Alleen toegang na een uitnodiging.</div></section></main>';
}
function renderAuth(){document.body.classList.remove('overlay-open');$('#overlay-root').innerHTML='';$('#toast-root').innerHTML='';$('#app').innerHTML=authMarkup();}
async function initialize(){
 $('#app').innerHTML='<div class="app-loading" role="status">Bouwberichten Dashboard laden…</div>';
 try{
  if(activationToken){try{const response=await api('/api/invitations/preview',{method:'POST',body:{token:activationToken},publicRequest:true});activation=response.invitation;}catch(error){authError=error.message;activationInvalid=true;}renderAuth();return;}
  session=await api('/api/session',{publicRequest:true});
  if(session.authenticated){if(location.pathname==='/login'||location.pathname==='/login/')history.replaceState(null,'','/#'+ui.route);if(session.user?.role!=='hoofdbeheerder'||!ui.companyId)ui.companyId=session.user.companyId;await refreshState(ui.companyId,{force:true});}else renderAuth();
 }catch(error){authError=error.message;renderAuth();}
}
async function authenticate(form,data){
 const activating=form.id==='activation-form';if(!activating)authRemember=data.rememberMe==='true';
 if(activating&&data.password!==data.passwordConfirm)throw Error('De wachtwoorden komen niet overeen.');
 if(activating&&data.password.length<12)throw Error('Gebruik een wachtwoord van minimaal 12 tekens.');
 authBusy=true;authError='';const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Even geduld…';
 try{
  session=await api(activating?'/api/auth/activate':'/api/auth/login',{method:'POST',body:activating?{token:activationToken,name:data.name,password:data.password}:{email:data.email,password:data.password,rememberMe:authRemember},publicRequest:true});
  activationToken=null;activation=null;authBusy=false;if(location.pathname==='/login'||location.pathname==='/login/')history.replaceState(null,'','/#'+ui.route);ui.companyId=session.user?.companyId||null;ui.drawer=null;ui.modal=null;await refreshState(ui.companyId,{force:true});
 }catch(error){authBusy=false;authError=error.message;renderAuth();}
}
function toast(text,tone='green'){const id=uid('toast');transient.push({id,text,tone});renderToasts();setTimeout(()=>{transient=transient.filter(t=>t.id!==id);renderToasts();},6500);}
function callbacks(){return state.leads.flatMap(l=>work(l).callbacks.map(cb=>({...cb,lead:l}))).filter(c=>!c.done).sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));}
function eligible(l){return callEligibility(state,l.id,company().id,currentUser().id);}
function filteredLeads(){return state.leads.filter(l=>{const w=work(l),q=ui.query.toLowerCase();return (!q||[l.title,l.organization,l.city,l.contact,...l.tags].join(' ').toLowerCase().includes(q))&&(ui.source==='all'||l.source===ui.source)&&(ui.priority==='all'||w.priority===ui.priority)&&(ui.status==='all'||w.status===ui.status)&&(ui.owner==='all'||w.ownerId===(ui.owner==='me'?currentUser().id:ui.owner))&&(ui.availability==='all'||eligible(l).allowed);}).sort((a,b)=>({high:0,medium:1,low:2}[work(a).priority]-{high:0,medium:1,low:2}[work(b).priority])||new Date(b.updatedAt)-new Date(a.updatedAt));}
function navTo(route){ui.route=route;ui.drawer=null;ui.modal=null;ui.mobile=false;location.hash=route;render();}
function btn(text,action,style='secondary',extra=''){return `<button type="button" class="button ${style}" data-action="${action}" ${extra}>${text}</button>`;}
function sourceBadge(source){return `<span class="source-chip source-${source}">${esc(names[source])}</span>`;}
function priorityBadge(p){return `<span class="priority ${p}">${esc(priorityNames[p])}</span>`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(company().name)}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(message='Geen leads gevonden.',action=''){return `<div class="empty-state">${icon('layers')}<h3>${message}</h3><p>Pas je filters aan of voeg een nieuwe lead toe.</p>${action}</div>`;}
function resetFilters(){Object.assign(ui,{query:'',source:'all',priority:'all',status:'all',owner:'all',availability:'all'});}
function render(){
 if(!state||!session?.authenticated){renderAuth();return;}
 if(!isChief())ui.companyId=currentUser().companyId;if(!state.companies.some(c=>c.id===ui.companyId))ui.companyId=state.companies[0].id;
 const page=routes.find(r=>r[0]===ui.route)||routes[0],due=callbacks().filter(c=>new Date(c.dueAt)<=Date.now()).length;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar ${ui.mobile?'open':''}"><a href="#dashboard" class="brand" data-route="dashboard">${dashboardBrand()}</a><div class="nav-label">WERKPLEK</div><nav class="nav-group" aria-label="Hoofdnavigatie">${routes.slice(0,7).map(([id,label,i])=>`<button class="nav-item ${ui.route===id?'active':''}" data-route="${id}" ${ui.route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='callbacks'&&due?`<span class="nav-count">${due}</span>`:''}</button>`).join('')}</nav><div class="nav-label">BEHEER</div><nav class="nav-group" aria-label="Beheer">${routes.slice(7).map(([id,label,i])=>`<button class="nav-item ${ui.route===id?'active':''}" data-route="${id}">${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-footer"><div class="sidebar-callout">${icon('shield')}<strong>Jouw bedrijf. Jouw opvolging.</strong><p>Centrale kansen, een eigen werkplek.</p></div><button class="profile-button" data-action="account"><span class="avatar">${esc(currentUser().name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><span><strong>${esc(currentUser().name)}</strong><small>${esc(currentUser().role)}</small></span>${icon('settings')}</button></div></aside><div class="workspace"><header class="topbar"><button class="button icon menu-toggle" data-action="menu" aria-label="Menu openen">${icon('menu')}</button><div class="breadcrumbs"><span>Werkplek</span>${icon('chevron')}<strong>${esc(page[1])}</strong></div><div class="top-actions"><span class="badge green hide-mobile">Gedeelde werkplek</span>${companyLogoSource(company())?`<img class="workspace-company-logo" src="${esc(companyLogoSource(company()))}" alt="Logo van ${esc(company().name)}">`:''}<label class="sr-only" for="company-switch">Actief bedrijf</label><select id="company-switch" class="company-switch" data-field="company" ${!isChief()?'disabled':''}>${state.companies.filter(c=>isChief()||c.id===ui.companyId).map(c=>`<option value="${c.id}" ${c.id===ui.companyId?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="button icon" data-route="callbacks" aria-label="Terugbelafspraken, ${due} verlopen">${icon('bell')}${due?'<span class="notification-dot"></span>':''}</button></div></header><main id="main" class="main" tabindex="-1">${renderPage()}<footer class="page-footer"><span>Bouwberichten Dashboard</span><span>Gedeeld opgeslagen · ${esc(company().name)} · tijdzone Amsterdam</span></footer></main></div></div>`;
 renderOverlay();renderToasts();save();
}
function renderPage(){switch(ui.route){case'leads':return leadsPage();case'kanban':return kanbanPage();case'calls':return callsPage();case'callbacks':return callbacksPage();case'feed':return feedPage();case'reports':return reportsPage();case'sources':return sourcesPage();case'team':return teamPage();case'settings':return settingsPage();default:return dashboardPage();}}
function dashboardPage(){const all=state.leads,available=all.filter(l=>eligible(l).allowed),todo=callbacks(),due=todo.filter(c=>new Date(c.dueAt)<=Date.now()),commitments=all.filter(l=>work(l).commitment).length,calc=all.filter(l=>work(l).calculation).length;return `${heading('Elke kans in beeld.','Van eerste signaal naar een goed gesprek. Dit is je werkvoorraad voor vandaag.',btn(`${icon('plus')} Nieuwe lead`,'new-lead','primary'))}<div class="stats-grid">${stat('Centrale leads',all.length,'Uit drie bronnen','layers','blue')}${stat('Nu te bellen',available.length,`${all.length-available.length} binnen de belwachttijd`,'phone','green')}${stat('Terugbelafspraken',todo.length,`${due.length} vragen nu aandacht`,'calendar','amber')}${stat('Toezeggingen',commitments,`${calc} klaar voor calculatie`,'chart','blue')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><div class="eyebrow">AAN DE SLAG</div><h2>Kansen om op te pakken</h2></div><button class="button ghost small" data-route="leads">Alle leads bekijken</button></div><div class="filter-row dashboard-filters"><div class="tabs"><button class="tab ${ui.availability==='all'?'active':''}" data-action="dash-filter" data-value="all">Alle kansen</button><button class="tab ${ui.availability==='available'?'active':''}" data-action="dash-filter" data-value="available">Nu belbaar</button><button class="tab ${ui.owner==='me'?'active':''}" data-action="dash-filter" data-value="me">Mijn leads</button></div></div>${leadTable(filteredLeads().slice(0,6),true)}<div class="panel-bottom"><span>${filteredLeads().length} kansen in je selectie</span><button class="button secondary small" data-route="calls">${icon('phone')} Open mijn bellijst</button></div></section><div class="dashboard-right"><section class="panel"><div class="panel-head"><h2>Je terugbelmomenten</h2><span class="badge amber">${due.length} openstaand</span></div><div class="panel-body callback-list">${todo.slice(0,3).map(callbackCard).join('')||'<p class="muted">Je planning is helemaal bij.</p>'}</div><button class="panel-link" data-route="callbacks">Bekijk de volledige planning</button></section><section class="panel"><div class="panel-head"><h2>Laatste signalen</h2>${icon('activity')}</div><div class="news-list">${feedItems().slice(0,3).map(newsItem).join('')}</div><button class="panel-link" data-route="feed">Open de nieuwsfeed</button></section></div></div><section class="sources-strip"><div>${icon('link')}<strong>Je bronnen, op één plek</strong><span class="muted">De bronconnectors zijn nog niet aangesloten.</span></div><div>${['bouw','hotels','vve'].map(s=>`${sourceBadge(s)}<span class="muted source-demo">Niet gekoppeld</span>`).join('')}<button class="button ghost small" data-route="sources">Beheer bronnen</button></div></section>`;}
function stat(label,value,meta,i,tone){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="stat-meta">${meta}</div></div>`;}
function filters(){return `<div class="toolbar"><label class="search">${icon('search')}<input id="lead-search" type="search" placeholder="Zoek project, organisatie of plaats…" aria-label="Zoek leads" data-field="query" value="${esc(ui.query)}"></label>${selectFilter('source','Bron',[['all','Alle bronnen'],['bouw','Bouwberichten.nl'],['hotels','Hotels'],['vve','VvE']])}${selectFilter('priority','Prioriteit',[['all','Alle prioriteiten'],...Object.entries(priorityNames)])}${selectFilter('status','Status',[['all','Alle statussen'],...company().columns.map(c=>[c.id,c.name])])}${selectFilter('owner','Verkoper',[['all','Alle verkopers'],['me','Mijn leads'],...activeUsers().map(u=>[u.id,u.name])])}<button class="button ghost small" data-action="reset-filters">Wis filters</button></div>`;}
function selectFilter(field,label,options){return `<label class="filter-select"><span class="sr-only">${label}</span><select data-field="${field}" aria-label="${label}">${options.map(([v,l])=>`<option value="${v}" ${ui[field]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function leadTable(leads,compact=false){if(!leads.length)return empty();return `<div class="table-wrap"><table><thead><tr><th>Project & organisatie</th><th>Bron</th><th>Prioriteit</th><th>Status</th>${compact?'':'<th>Verkoper</th>'}<th>Opvolging</th><th><span class="sr-only">Openen</span></th></tr></thead><tbody>${leads.map(l=>{const w=work(l),e=eligible(l);return `<tr><td><button class="lead-title" data-action="open-lead" data-id="${l.id}">${esc(l.title)}</button><div class="lead-meta">${esc(l.organization)} <span>·</span> ${esc(l.city)}</div></td><td>${sourceBadge(l.source)}</td><td>${priorityBadge(w.priority)}</td><td><span class="status-pill status-${company().columns.findIndex(c=>c.id===w.status)}">${esc(statusName(w.status))}</span></td>${compact?'':`<td><span class="seller-cell">${esc(w.ownerId?userName(w.ownerId):'Niet toegewezen')}</span></td>`}<td><span class="call-state ${e.allowed?'available':'waiting'}">${icon(e.allowed?'phone':'clock')}${e.reason==='callback'?'Eigen terugbelmoment':e.allowed?'Nu belbaar':'Wachttijd'}</span><div class="lead-meta">${w.commitment?'Toezegging':''}${w.commitment&&w.calculation?' · ':''}${w.calculation?'Calculatie':''}</div></td><td><button class="button icon small" data-action="open-lead" data-id="${l.id}" aria-label="Open ${esc(l.title)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function leadsPage(){return `${heading('Alle leads','Eén centrale voorraad. De opvolging die je hier ziet, hoort bij je actieve bedrijf.',`${btn(`${icon('download')} Exporteer selectie`,'export','secondary')}${btn(`${icon('plus')} Nieuwe lead`,'new-lead','primary')}`)}<section class="panel">${filters()}<div class="section-heading"><strong>${filteredLeads().length} leads</strong><span class="muted">Statussen en notities van ${esc(company().name)}</span></div>${leadTable(filteredLeads())}</section>`;}
function kanbanPage(){
 const columns=company().columns.map((c,i)=>{
  const selected=filteredLeads().filter(l=>work(l).status===c.id);
  const cards=c.id==='opvolgen'?sortFollowUpLeads(state,company().id,selected):selected;
  return `<section class="kanban-column" data-column="${c.id}" aria-label="${esc(c.name)}"><div class="kanban-head"><span class="column-marker marker-${i}"></span><h2>${esc(c.name)}</h2><span class="column-count">${cards.length}</span>${canManage()?`<button class="button icon small" data-action="columns" aria-label="Kolom ${esc(c.name)} hernoemen">${icon('edit')}</button>`:''}</div>${cards.map(l=>{
   const w=work(l),next=c.id==='opvolgen'?nextFollowUpAt(state,company().id,l.id):null;
   const followUp=c.id==='opvolgen'?`<div class="kanban-date ${next&&Date.parse(next)<=Date.now()?'overdue':''}">${icon('clock')}${next?`<time datetime="${next}">${fmt(next)}</time>`:'<span class="muted">Geen terugbelmoment</span>'}</div>`:'';
   return `<article class="kanban-card" draggable="true" data-lead="${l.id}" data-action="open-lead" data-id="${l.id}" role="button" tabindex="0" aria-haspopup="dialog" aria-label="Open ${esc(l.title)}"><div class="card-top">${sourceBadge(l.source)}${priorityBadge(w.priority)}</div><h3 class="lead-title">${esc(l.title)}</h3><p class="lead-meta">${esc(l.organization)}<br>${esc(l.city)}</p>${followUp}<div class="card-tags">${w.commitment?'<span class="badge green">Toezegging</span>':''}${w.calculation?'<span class="badge blue">Calculatie</span>':''}</div><div class="card-footer"><span>${esc(w.ownerId?userName(w.ownerId).split(' ')[0]:'Niet toegewezen')}</span><span>${icon('mail')} ${w.notes.length} notities</span></div></article>`;
  }).join('')}<button class="kanban-add" data-action="new-lead" data-status="${c.id}">${icon('plus')} Lead toevoegen</button></section>`;
 }).join('');
 return `${heading('Van kans naar opdracht','Klik op een kaart om de lead te openen of sleep deze naar een andere kolom.',`${canManage()?btn(`${icon('edit')} Kolommen beheren`,'columns'):''}${btn(`${icon('plus')} Nieuwe lead`,'new-lead','primary')}`)}${filters()}<div class="kanban">${columns}</div><p class="muted help-text">Opvolgen staat op datum van het vroegste open terugbelmoment, de vroegste datum bovenaan. Leads zonder terugbelmoment staan onderaan.</p>`;
}
function callsPage(){const leads=filteredLeads(),available=leads.filter(l=>eligible(l).allowed);return `${heading('Een goed gesprek begint hier','Werk je prioriteiten af. Een belregistratie start de wachttijd voor andere bedrijven.',btn(`${icon('download')} Exporteer bellijst`,'export'))}<div class="call-summary"><div>${icon('phone')}<strong>${available.length} leads nu belbaar</strong></div><span>Globale wachttijd: <strong>${state.settings.cooldownHours} uur</strong> · Eigen vervallen terugbelafspraken hebben voorrang.</span>${btn('Instellingen','go-settings','ghost small')}</div><section class="panel">${filters()}<div class="filter-row"><label class="check-row"><input type="checkbox" data-field="available-check" ${ui.availability==='available'?'checked':''}> Alleen nu belbare leads</label></div>${leadTable(leads)}</section>`;}
function callbackCard(c){const due=new Date(c.dueAt)<=Date.now();return `<article class="callback-card"><div class="callback-time ${due?'overdue':''}">${icon('clock')} ${due?'Nu opvolgen · ':''}${fmt(c.dueAt)}</div><button class="lead-title" data-action="open-lead" data-id="${c.lead.id}">${esc(c.lead.title)}</button><p class="lead-meta">Voor ${esc(userName(c.assigneeId))} · Gemaakt door ${esc(c.creatorName)}</p><div class="callback-actions">${btn('Open lead','open-lead','ghost small',`data-id="${c.lead.id}"`)}${btn(`${icon('check')} Afgehandeld`,'complete-callback','secondary small',`data-id="${c.id}" data-lead-id="${c.lead.id}"`)}</div></article>`;}
function callbacksPage(){const all=callbacks(),due=all.filter(c=>new Date(c.dueAt)<=Date.now());return `${heading('Geen terugbelmoment missen','Afspraken voor jou en je collega’s. De maker blijft zichtbaar bij iedere afspraak.',(state.leads.length?btn(`${icon('plus')} Terugbelafspraak`,'callback','primary'):btn(`${icon('plus')} Nieuwe lead`,'new-lead','primary')))}<div class="stats-grid compact-stats">${stat('Open afspraken',all.length,'Binnen dit bedrijf','calendar','blue')}${stat('Nu opvolgen',due.length,'Vervallen terugbelmomenten','clock','amber')}${stat('Voor mij',all.filter(c=>c.assigneeId===currentUser().id).length,'Persoonlijk toegewezen','users','green')}</div><section class="panel"><div class="panel-head"><h2>Planning van ${esc(company().name)}</h2><span class="badge neutral">${all.length} afspraken</span></div><div class="callback-grid panel-body">${all.map(callbackCard).join('')||'<div class="empty-state"><h3>Alle afspraken zijn afgehandeld</h3><p>Maak een nieuwe terugbelafspraak vanuit een lead.</p></div>'}</div></section><p class="muted help-text">Meldingen rechtsonder verschijnen in dit geopende dashboard. Collega’s zien wijzigingen automatisch binnen ongeveer 30 seconden.</p>`;}
function feedItems(){const items=state.feed.filter(f=>!f.companyId||f.companyId===company().id);const overdue=callbacks().filter(c=>new Date(c.dueAt)<=Date.now()).map(c=>({id:'signal-'+c.id,leadId:c.lead.id,type:'followup',text:`Terugbelmoment voor ${userName(c.assigneeId)}: ${c.lead.title}`,authorName:c.creatorName,at:c.dueAt,companyId:company().id}));return [...overdue,...items].filter(f=>ui.feedFilter==='all'||(ui.feedFilter==='source'?!f.companyId:f.type==='followup')).sort((a,b)=>new Date(b.at)-new Date(a.at));}
function newsItem(f){const lead=state.leads.find(l=>l.id===f.leadId),isGlobal=!f.companyId;return `<article class="news-item"><span class="news-icon ${f.type==='followup'?'amber':isGlobal?'blue':'green'}">${icon(f.type==='followup'?'clock':isGlobal?'layers':'activity')}</span><div class="news-body"><span class="news-kicker">${isGlobal?'CENTRALE PROJECTUPDATE':f.type==='followup'?'OPVOLGSIGNAAL':'JOUW BEDRIJF'}</span><p>${esc(f.text)}</p><div class="news-time">${fmt(f.at)} · ${esc(f.authorName||'Demobron')}${lead?` · <button data-action="open-lead" data-id="${lead.id}" class="text-link">Bekijk lead</button>`:''}</div></div></article>`;}
function feedPage(){return `${heading('Wat speelt er?','Nieuwe leads, projectwijzigingen en signalen om op te volgen. Alle bronupdates zijn demonstraties.')}<section class="panel"><div class="filter-row"><div class="tabs">${[['all','Alle signalen'],['source','Projectupdates'],['followup','Opvolgsignalen']].map(([v,l])=>`<button class="tab ${ui.feedFilter===v?'active':''}" data-action="feed-filter" data-value="${v}">${l}</button>`).join('')}</div></div><div class="news-list full-news">${feedItems().map(newsItem).join('')||empty('Geen signalen in deze selectie.')}</div></section>`;}
function reportsPage(){const cid=isChief()?(ui.reportCompany==='current'?company().id:ui.reportCompany):company().id;const rows=reportRows(state,{companyId:cid,sellerId:ui.reportSeller,source:ui.reportSource,from:ui.reportFrom,to:ui.reportTo});const sum=k=>rows.reduce((n,r)=>n+r[k],0),total=sum('total'),comm=sum('commitments'),calc=sum('calculations'),contacted=sum('contacted');const aggregate=(key,name)=>{const m=new Map();rows.forEach(r=>{const id=r[key];const a=m.get(id)||{name:name(r),total:0,commitments:0,calculations:0};a.total+=r.total;a.commitments+=r.commitments;a.calculations+=r.calculations;m.set(id,a);});return [...m.values()];};return `${heading('Van activiteit naar resultaat','Bekijk conversie per bedrijf, verkoper en bron. De cijfers volgen de opgeslagen opvolging van jouw selectie.',btn(`${icon('download')} Rapport exporteren`,'export-report'))}<section class="panel report-filters"><div class="toolbar">${isChief()?`<label class="field"><span>Bedrijf</span><select data-field="reportCompany"><option value="current" ${ui.reportCompany==='current'?'selected':''}>Actief bedrijf</option><option value="all" ${ui.reportCompany==='all'?'selected':''}>Alle bedrijven</option>${state.companies.map(c=>`<option value="${c.id}" ${ui.reportCompany===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:''}<label class="field"><span>Verkoper</span><select data-field="reportSeller"><option value="all">Alle verkopers</option>${state.users.filter(u=>cid==='all'||u.companyId===cid||Object.values(state.workspaces[cid]||{}).some(w=>w.ownerId===u.id)).map(u=>`<option value="${u.id}" ${ui.reportSeller===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label class="field"><span>Bron</span><select data-field="reportSource">${[['all','Alle bronnen'],['bouw',names.bouw],['hotels','Hotels'],['vve','VvE']].map(([v,l])=>`<option value="${v}" ${ui.reportSource===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Lead aangemaakt vanaf</span><input type="date" value="${ui.reportFrom}" data-field="reportFrom"></label><label class="field"><span>Tot en met</span><input type="date" value="${ui.reportTo}" data-field="reportTo"></label>${btn('Wis filters','reset-report','ghost small')}</div></section><div class="stats-grid">${stat('Toegewezen leads',total,'Selectie op aanmaakdatum lead','layers','blue')}${stat('Gesproken / gebeld',contacted,'Leads met een belregistratie','phone','green')}${stat('Toezeggingen',comm,`${total?Math.round(comm/total*100):0}% van toegewezen leads`,'check','green')}${stat('Klaar voor calculatie',calc,`${total?Math.round(calc/total*100):0}% van toegewezen leads`,'chart','blue')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Conversie per bron</h2><span class="badge blue">Toezeggingen</span></div><div class="panel-body">${aggregate('source',r=>names[r.source]).map(r=>chartRow(r)).join('')||'<p class="muted">Geen gegevens in deze selectie.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>${cid==='all'?'Conversie per bedrijf':'Conversie per verkoper'}</h2></div><div class="panel-body">${aggregate(cid==='all'?'companyId':'sellerId',r=>cid==='all'?r.companyName:r.sellerName).map(r=>chartRow(r)).join('')||'<p class="muted">Geen gegevens in deze selectie.</p>'}</div></section></div><section class="panel"><div class="panel-head"><h2>Resultaten in detail</h2><span class="muted">${rows.length} combinaties</span></div><div class="table-wrap"><table><thead><tr><th>Bedrijf</th><th>Verkoper</th><th>Bron</th><th>Leads</th><th>Gebeld</th><th>Toezegging</th><th>Calculatie</th><th>Conversie</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.companyName)}</td><td>${esc(r.sellerName)}</td><td>${sourceBadge(r.source)}</td><td>${r.total}</td><td>${r.contacted}</td><td>${r.commitments}</td><td>${r.calculations}</td><td><strong>${Math.round(r.conversion)}%</strong></td></tr>`).join('')||'<tr><td colspan="8">Geen resultaten.</td></tr>'}</tbody></table></div></section><div class="report-definition"><strong>Zo rekenen we</strong><p>Conversie = leads met toezegging ÷ toegewezen leads. Calculatie heeft een eigen percentage en is een apart vinkje. De periode selecteert de aanmaakdatum van de centrale lead; de vinkjes tonen de huidige stand. Niet toegewezen leads tellen niet mee. Bij overplaatsing blijven resultaten bij het oorspronkelijke bedrijf en de vastgelegde verkoper.</p></div>`;}
function chartRow(r){const n=r.total?Math.round(r.commitments/r.total*100):0;return `<div class="chart-row"><div class="chart-label"><strong>${esc(r.name)}</strong><span>${r.commitments} van ${r.total} leads</span></div><div class="chart-track"><div class="chart-fill" style="width:${n}%"></div></div><span class="chart-value">${n}%</span></div>`;}
function sourcesPage(){return `${heading('Een centrale plek voor je bronnen','Bereid je bronnen voor. Er worden in dit prototype geen gegevens opgehaald en geen inloggegevens verstuurd.')}<div class="integration-grid">${state.sources.map(s=>`<section class="integration-card"><div class="integration-card-top"><span class="integration-icon ${s.id==='outlook'?'blue':''}">${icon(s.id==='outlook'?'mail':s.id==='hotels'?'building':s.id==='vve'?'users':'layers')}</span><span class="badge ${s.id==='outlook'?'neutral':'amber'}">${s.id==='outlook'?'Toekomstig':'Niet gekoppeld'}</span></div><h2>${esc(s.name)}</h2><p>${s.id==='bouw'?'Projectkansen uit de bouw, centraal beschikbaar voor ieder bedrijf.':s.id==='hotels'?'Hotelprojecten, renovaties en contactgegevens op één plek.':s.id==='vve'?'Onderhouds- en renovatiekansen bij verenigingen van eigenaars.':'Later: e-mails matchen op contact, organisatie en project. Alleen na toestemming.'}</p><div class="integration-meta"><strong>${s.id==='outlook'?'0 gekoppelde mailboxen':state.leads.filter(l=>l.source===s.id).length+' leads'}</strong><span>${s.id==='outlook'?'Nog geen e-mailtoegang':'Laatste echte synchronisatie: nooit'}</span></div>${s.url?`<div class="configured-url">Ingestelde URL: ${esc(s.url)}</div>`:''}${isChief()?btn(s.id==='outlook'?'Bekijk koppelplan':'Bron configureren','source-config','secondary',`data-id="${s.id}"`):'<p class="muted">De hoofdbeheerder beheert deze bron.</p>'}</section>`).join('')}</div><section class="panel security-panel"><div class="panel-body split">${icon('shield')}<div><h2>Klaar voor veilige connectors</h2><p>Je kunt nu de bron-URL en een gebruikersnaam voorbereiden. Echte toegang loopt later via een serverconnector met versleutelde geheimen of OAuth. De bronvoorbereiding vraagt of bewaart geen wachtwoorden. Outlook krijgt een afzonderlijke toestemmingsstap en een controle op de e-mailmatching.</p></div></div></section>`;}
function inviteStatus(i){if(i.status==='revoked')return 'Ingetrokken';if(i.status==='accepted'||i.status==='used')return 'Geaccepteerd';if(i.status==='expired'||new Date(i.expiresAt)<=Date.now())return 'Verlopen';return 'Openstaand';}
function inviteOpen(i){return !['revoked','accepted','used'].includes(i.status);}
function teamPage(){
 const cs=isChief()?state.companies:state.companies.filter(c=>c.id===company().id),users=state.users.filter(u=>cs.some(c=>c.id===u.companyId)),invs=state.invitations.filter(i=>cs.some(c=>c.id===i.companyId));
 return heading('Bedrijven & mensen','Iedere gebruiker hoort bij één bedrijf. Maak een persoonlijke link om iemand toegang te geven.',(isChief()?btn(icon('plus')+' Bedrijf toevoegen','new-company'):'')+(canManage()?btn(icon('link')+' Uitnodigingslink maken','invite','primary'):''))+
 '<div class="company-grid">'+cs.map(c=>`<section class="company-card ${c.id===company().id?'selected':''}">${companyLogoMarkup(c)}<div><h2>${esc(c.name)}</h2><p>${state.users.filter(u=>u.companyId===c.id).length} gebruikers · ${c.columns.length} Kanban-kolommen</p></div><div class="company-card-actions">${isChief()?btn(c.id===company().id?'Actieve werkplek':'Open werkplek','switch-company','ghost small',`data-id="${esc(c.id)}"`):'<span class="badge blue">Jouw bedrijf</span>'}${canManage()?btn(`${icon('edit')} Bewerken`,'edit-company','secondary small',`data-id="${esc(c.id)}" aria-label="Bewerk ${esc(c.name)}"`):''}</div></section>`).join('')+'</div>'+
 '<section class="panel"><div class="panel-head"><h2>Gebruikers</h2><span class="badge neutral">'+users.length+' personen</span></div><div class="table-wrap"><table><thead><tr><th>Naam</th><th>E-mailadres</th><th>Bedrijf</th><th>Rol</th><th>Status</th>'+(isChief()?'<th>Beheer</th>':'')+'</tr></thead><tbody>'+users.map(u=>'<tr><td><strong>'+esc(u.name)+'</strong>'+(u.id===currentUser().id?'<span class="badge blue inline-badge">Jij</span>':'')+'</td><td>'+esc(u.email)+'</td><td>'+esc(companyName(u.companyId))+'</td><td>'+esc(u.role)+'</td><td><span class="badge '+(u.status==='uitgenodigd'?'amber':'green')+'">'+(u.status==='uitgenodigd'?'Uitgenodigd':'Actief')+'</span></td>'+(isChief()?'<td>'+btn('Aanpassen','edit-user','ghost small','data-id="'+u.id+'"')+'</td>':'')+'</tr>').join('')+'</tbody></table></div></section>'+
 '<section class="panel"><div class="panel-head"><div><h2>Uitnodigingslinks</h2><p>Deel de link zelf met de bedoelde ontvanger. Er wordt geen e-mail verzonden.</p></div><span class="badge blue">Eenmalig · 7 dagen geldig</span></div><div class="table-wrap"><table><thead><tr><th>E-mailadres</th><th>Bedrijf</th><th>Rol</th><th>Status en verloopdatum</th><th>Actie</th></tr></thead><tbody>'+invs.map(i=>'<tr><td><strong>'+esc(i.name)+'</strong><div>'+esc(i.email)+'</div></td><td>'+esc(companyName(i.companyId))+'</td><td>'+esc(i.role)+'</td><td><span class="badge '+(inviteStatus(i)==='Openstaand'?'blue':'neutral')+'">'+inviteStatus(i)+'</span><div class="lead-meta">'+fmt(i.expiresAt)+'</div></td><td>'+(canManage()&&inviteOpen(i)?btn('Nieuwe link','rotate-invite','secondary small','data-id="'+i.id+'"')+' '+btn('Intrekken','revoke-invite','ghost small','data-id="'+i.id+'"'):'—')+'</td></tr>').join('')+(invs.length?'':'<tr><td colspan="5" class="muted">Nog geen uitnodigingen. Maak een link om een collega uit te nodigen.</td></tr>')+'</tbody></table></div></section>'+
 '<div class="report-definition"><strong>Rollen en toegang</strong><p>De hoofdbeheerder beheert alle bedrijven en bronnen. Bedrijfsbeheerders nodigen mensen uit voor hun eigen bedrijf. Verkopers werken binnen hun eigen werkplek. De server controleert de toegang; notities en opvolging blijven bij het oorspronkelijke bedrijf.</p></div>';
}
function settingsPage(){return heading('Heldere afspraken, betere opvolging','De belwachttijd is één globale instelling en geldt ook voor nieuwe bedrijven.')+'<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Belwachttijd tussen bedrijven</h2>'+icon('clock')+'</div><form id="cooldown-form" class="panel-body"><p>Na een belregistratie op een centrale lead wacht een ander bedrijf de ingestelde periode. Dit geldt alleen voor die lead.</p><label class="field"><span>Globale wachttijd in uren</span><input name="hours" type="number" min="0" max="8760" step="1" required value="'+state.settings.cooldownHours+'" '+(!isChief()?'disabled':'')+'></label><div class="info-box"><strong>Uitzondering: eigen terugbelafspraak</strong><p>Is een open terugbelafspraak aan jou toegewezen en is het tijdstip bereikt? Dan kun je die lead bellen, ook als een ander bedrijf recent heeft gebeld.</p></div>'+(isChief()?'<button class="button primary" type="submit">Instelling opslaan</button>':'<p class="muted">Alleen de hoofdbeheerder kan dit wijzigen.</p>')+'</form></section><section class="panel"><div class="panel-head"><h2>Jouw werkplek</h2>'+icon('shield')+'</div><div class="panel-body"><p><strong>'+esc(company().name)+'</strong><br>'+esc(currentUser().name)+' · '+esc(currentUser().role)+'</p><p>Je wijzigingen worden op de server opgeslagen en gedeeld met je collega’s. De externe bronconnectors en Outlook zijn nog niet gekoppeld.</p>'+btn('Mijn account','account')+'<p class="muted help-text">Meldingen verschijnen in het geopende dashboard. Wijzigingen van collega’s worden iedere 30 seconden opgehaald.</p></div></section></div>';}

function renderOverlay(){const root=$('#overlay-root');const oldBody=root.querySelector('.detail-body');if(oldBody&&oldBody.closest('[data-drawer-id]')?.dataset.drawerId===ui.drawer)drawerScroll=oldBody.scrollTop;if(ui.modal){root.innerHTML=modalHTML();updateCompanyLogoPreview();requestAnimationFrame(()=>root.querySelector('input:not([type=hidden]),select,button')?.focus());}else if(ui.drawer){root.innerHTML=drawerHTML();const body=root.querySelector('.detail-body');if(body)body.scrollTop=drawerScroll;}else root.innerHTML='';document.body.classList.toggle('overlay-open',!!(ui.modal||ui.drawer));}
function drawerHTML(){const l=state.leads.find(x=>x.id===ui.drawer);if(!l)return '';const w=work(l),e=eligible(l),members=activeUsers(),historic=w.ownerId&&!members.some(u=>u.id===w.ownerId);return `<div class="detail-overlay" data-action="close-drawer"></div><aside class="detail-drawer" data-drawer-id="${l.id}" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="detail-header"><div>${sourceBadge(l.source)}<span class="badge neutral">${l.demo?'Demolead':'Handmatig toegevoegd'}</span></div><button class="button icon" data-action="close-drawer" aria-label="Lead sluiten">${icon('close')}</button></div><div class="detail-body"><div class="eyebrow">${esc(l.city)} · ${esc(l.phase)}</div><h2 id="detail-title" tabindex="-1">${esc(l.title)}</h2><p class="lead-organization">${esc(l.organization)}</p><p>${esc(l.description)}</p><div class="detail-section contact-box"><strong>${esc(l.contact)}</strong><div class="contact-links">${e.allowed?`<a class="button primary" href="tel:${esc(l.phone.replace(/[^+\d]/g,''))}" data-action="call-link" data-id="${l.id}">${icon('phone')} ${esc(l.phone)}</a>`:`<span class="button disabled" aria-disabled="true">${icon('clock')} Tijdelijk niet belbaar</span>`}<a class="button secondary" href="mailto:${esc(l.email)}">${icon('mail')} E-mail</a></div><p class="muted">${esc(l.email)}${l.demo?' · Fictieve contactgegevens':''}</p>${e.reason==='cooldown'?`<div class="call-notice amber"><strong>Wachttijd tot ${fmt(e.until)}</strong><p>Een ander bedrijf heeft deze lead recent gebeld. Gespreksdetails blijven afgeschermd.</p></div>`:e.reason==='callback'?'<div class="call-notice green">Je eigen terugbelmoment is bereikt. De wachttijd geldt nu niet voor jou.</div>':'<p class="call-state available">Beschikbaar om te bellen</p>'}<div class="split">${btn('Bellen registreren','register-call','secondary small',`data-id="${l.id}" ${!e.allowed?'disabled':''}`)}<span class="muted small-text">Start de wachttijd; tel-link doet dit ook.</span></div></div><div class="detail-section"><h3>Opvolging bij ${esc(company().name)}</h3><div class="form-grid"><label class="field"><span>Kanban-status</span><select data-work="status" data-id="${l.id}">${company().columns.map(c=>`<option value="${c.id}" ${w.status===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field"><span>Prioriteit</span><select data-work="priority" data-id="${l.id}">${Object.entries(priorityNames).map(([v,n])=>`<option value="${v}" ${w.priority===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field full"><span>Verantwoordelijke verkoper</span><select data-work="ownerId" data-id="${l.id}"><option value="">Niet toegewezen</option>${historic?`<option value="${w.ownerId}" selected>${esc(userName(w.ownerId))} (historisch)</option>`:''}${members.map(u=>`<option value="${u.id}" ${w.ownerId===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div><div class="conversion-checks"><label class="check-row"><input type="checkbox" data-work="commitment" data-id="${l.id}" ${w.commitment?'checked':''}><span><strong>Toezegging ontvangen</strong><small>De klant heeft een toezegging gedaan.</small></span></label><label class="check-row"><input type="checkbox" data-work="calculation" data-id="${l.id}" ${w.calculation?'checked':''}><span><strong>Klaar voor calculatie</strong><small>De informatie kan naar de calculator.</small></span></label></div><p class="muted help-text">Deze vinkjes staan los van elkaar en van de Kanban-status.</p></div><div class="detail-section"><div class="section-heading"><h3>Terugbelafspraken</h3>${btn(`${icon('plus')} Inplannen`,'callback','ghost small',`data-id="${l.id}"`)}</div>${w.callbacks.filter(c=>!c.done).map(c=>callbackCard({...c,lead:l})).join('')||'<p class="muted">Nog geen open terugbelafspraak.</p>'}</div><div class="detail-section"><h3>Gespreksnotities <span class="badge neutral">${w.notes.length}</span></h3><form id="note-form"><input type="hidden" name="leadId" value="${l.id}"><label class="field"><span class="sr-only">Nieuwe notitie</span><textarea name="text" placeholder="Wat is besproken? Wat is de volgende stap?" maxlength="4000" required rows="3"></textarea></label><button class="button primary small" type="submit">Notitie toevoegen</button></form><div class="notes-list">${[...w.notes].reverse().map(n=>`<article class="note"><div class="note-meta"><strong>${esc(n.authorName)}</strong><span>${fmt(n.createdAt)}</span></div><p>${esc(n.text).replace(/\n/g,'<br>')}</p></article>`).join('')||'<p class="muted">Notities zijn alleen zichtbaar binnen dit bedrijf.</p>'}</div></div><div class="detail-section"><h3>Belgeschiedenis van dit bedrijf</h3>${[...w.calls].reverse().map(c=>`<div class="history-row">${icon('phone')}<span>${esc(c.userName||userName(c.userId))}</span><time>${fmt(c.at)}</time></div>`).join('')||'<p class="muted">Nog geen belregistraties.</p>'}</div><div class="detail-section"><h3>Projectinformatie</h3><dl class="project-facts"><dt>Fase</dt><dd>${esc(l.phase)}</dd><dt>Projectomvang</dt><dd>${esc(l.budget)}</dd><dt>Laatst gewijzigd</dt><dd>${fmt(l.updatedAt)}</dd></dl><div class="card-tags">${l.tags.map(t=>`<span class="badge neutral">${esc(t)}</span>`).join('')}</div></div></div></aside>`;}
function modalShell(title,body,footer='',wide=false){return `<div class="modal-backdrop" data-action="close-modal"></div><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="button icon" data-action="close-modal" aria-label="Venster sluiten">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;}
function formButtons(label='Opslaan'){return `<div class="modal-form-actions">${btn('Annuleren','close-modal')}<button type="submit" class="button primary">${label}</button></div>`;}
function modalHTML(){const m=ui.modal;switch(m.type){
case'edit-company':{const c=state.companies.find(item=>item.id===m.id);return c?companyEditorHTML(c):modalShell('Bedrijf niet gevonden','<p>Sluit dit venster en vernieuw de pagina.</p>',btn('Sluiten','close-modal'));}
case'demo-info':return modalShell('Je gedeelde werkplek','<p>Accounts, uitnodigingslinks, notities, Kanban, belregistraties en terugbelafspraken werken met gedeelde opslag op de server.</p><div class="info-box"><strong>Bronnen en gegevens</strong><p>Zelf toegevoegde leads en jullie opvolging worden gedeeld opgeslagen. Bouwberichten.nl, hotels, VvE en Outlook zijn nog niet aangesloten.</p></div><p>Uitnodigingslinks geven echte toegang aan de bedoelde gebruiker. Deel ze zelf; het dashboard verstuurt geen e-mails. Meldingen verschijnen wanneer het dashboard geopend is.</p>',btn('Begrepen','close-modal','primary'));
case'account':return modalShell('Mijn account','<div class="account-summary"><span class="avatar">'+esc(currentUser().name.split(' ').map(s=>s[0]).slice(0,2).join(''))+'</span><div><strong>'+esc(currentUser().name)+'</strong><p>'+esc(currentUser().email)+'</p></div></div><dl class="project-facts"><dt>Bedrijf</dt><dd>'+esc(companyName(currentUser().companyId))+'</dd><dt>Rol</dt><dd>'+esc(currentUser().role)+'</dd></dl><p class="muted">Je toegang hoort bij één bedrijf. De hoofdbeheerder kan je koppeling aanpassen.</p>',btn('Sluiten','close-modal')+btn('Uitloggen','logout','primary'));
case'invite-link':return modalShell('Je uitnodigingslink is klaar','<p>Deel deze persoonlijke link met <strong>'+esc(m.invitation?.name||m.invitation?.email||'de ontvanger')+'</strong>. De link werkt één keer en vervalt na zeven dagen.</p><label class="field"><span>Persoonlijke uitnodigingslink</span><input id="invite-link" type="text" readonly value="'+esc(m.inviteUrl)+'" autocomplete="off"></label><p class="muted help-text">De volledige link wordt alleen nu getoond. Later kun je een nieuwe link maken; de vorige werkt dan niet meer.</p><div class="info-box"><strong>Geen e-mail verzonden</strong><p>Kopieer de link en stuur hem zelf naar het ingevulde e-mailadres.</p></div>',btn(icon('link')+' Link kopiëren','copy-invite','primary')+btn('Gereed','close-modal'));

case'new-lead':return modalShell('Een nieuwe kans toevoegen',`<form id="lead-form"><div class="form-grid"><label class="field full"><span>Projectnaam</span><input name="title" required maxlength="150" placeholder="Bijv. Renovatie Stationskwartier"></label><label class="field"><span>Organisatie</span><input name="organization" required maxlength="120"></label><label class="field"><span>Plaats</span><input name="city" required maxlength="100"></label><label class="field"><span>Broncategorie</span><select name="source">${['bouw','hotels','vve'].map(s=>`<option value="${s}">${names[s]}</option>`).join('')}</select></label><label class="field"><span>Contactpersoon</span><input name="contact" required maxlength="100"></label><label class="field"><span>Telefoon</span><input name="phone" type="tel" required maxlength="30" pattern="[+0-9 ()-]{6,30}"></label><label class="field"><span>E-mailadres</span><input name="email" type="email" required maxlength="160"></label><label class="field full"><span>Projectomschrijving</span><textarea name="description" required maxlength="3000" rows="3"></textarea></label></div><p class="muted">De lead wordt centraal zichtbaar voor alle bedrijven. Opvolging blijft per bedrijf.</p>${formButtons('Lead toevoegen')}</form>`, '',true);
case'callback':{if(!state.leads.length)return modalShell('Nog geen leads','<p>Voeg eerst een lead toe om een terugbelafspraak te plannen.</p>',btn('Lead toevoegen','new-lead','primary'));const id=m.id||ui.drawer||state.leads[0].id;const d=new Date(Date.now()+86400000);const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);return modalShell('Een terugbelmoment plannen',`<form id="callback-form"><label class="field"><span>Lead</span><select name="leadId">${state.leads.map(l=>`<option value="${l.id}" ${l.id===id?'selected':''}>${esc(l.title)}</option>`).join('')}</select></label><div class="form-grid"><label class="field"><span>Datum en tijd (Amsterdam)</span><input type="datetime-local" name="dueAt" required value="${parts}T09:00"></label><label class="field"><span>Voor wie?</span><select name="assigneeId">${activeUsers().map(u=>`<option value="${u.id}" ${u.id===currentUser().id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div><p class="muted">Gemaakt door ${esc(currentUser().name)}. Collega’s zien de afspraak in deze werkplek en een melding wanneer het tijd is.</p>${formButtons('Afspraak opslaan')}</form>`);}
case'columns':return modalShell('Kolommen van jouw bedrijf',`<p>Hernoemen wijzigt de bestaande kaarten niet. Kolommen van andere bedrijven blijven behouden.</p><form id="columns-form">${company().columns.map(c=>`<label class="field"><span>Kolomnaam</span><input name="col-${c.id}" value="${esc(c.name)}" maxlength="35" required></label>`).join('')}<label class="field"><span>Nieuwe kolom (optioneel)</span><input name="newColumn" maxlength="35" placeholder="Bijv. Wachten op informatie"></label>${formButtons('Kolommen opslaan')}</form>`);
case'new-company':return modalShell('Bedrijf toevoegen',`<form id="company-form"><label class="field"><span>Bedrijfsnaam</span><input name="name" required maxlength="120" placeholder="Naam van het bedrijf"></label><p>Het bedrijf krijgt een eigen Kanban-bord en eigen opvolging voor alle centrale leads. De globale belwachttijd geldt automatisch.</p>${formButtons('Bedrijf toevoegen')}</form>`);
case'invite':return modalShell('Een gebruiker uitnodigen','<p>Maak een persoonlijke activatielink. De ontvanger kiest zelf een wachtwoord en wordt aan precies één bedrijf gekoppeld.</p><form id="invite-form"><label class="field"><span>Volledige naam</span><input name="name" required maxlength="100" autocomplete="name"></label><label class="field"><span>E-mailadres</span><input name="email" type="email" required maxlength="160" autocomplete="email"></label><div class="form-grid"><label class="field"><span>Eén bedrijf</span><select name="companyId">'+state.companies.filter(c=>isChief()||c.id===company().id).map(c=>'<option value="'+c.id+'" '+(c.id===company().id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label class="field"><span>Rol</span><select name="role"><option value="verkoper">Verkoper</option><option value="bedrijfsbeheerder">Bedrijfsbeheerder</option>'+(isChief()?'<option value="hoofdbeheerder">Hoofdbeheerder</option>':'')+'</select></label></div><p class="muted help-text">De link is zeven dagen geldig. Er wordt geen e-mail verzonden; je deelt de link zelf.</p>'+formButtons('Uitnodigingslink maken')+'</form>');

case'edit-user':{const u=state.users.find(u=>u.id===m.id);return modalShell('Gebruiker aanpassen',`<p><strong>${esc(u.name)}</strong><br>${esc(u.email)}</p><form id="user-form"><input type="hidden" name="userId" value="${u.id}"><label class="field"><span>Bedrijf</span><select name="companyId">${state.companies.map(c=>`<option value="${c.id}" ${u.companyId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field"><span>Rol</span><select name="role">${['hoofdbeheerder','bedrijfsbeheerder','verkoper'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label><div class="info-box"><strong>Historie blijft bewaard</strong><p>Bij overplaatsing blijven notities, afspraken en resultaten bij het oorspronkelijke bedrijf. De gebruiker ziet daarna de nieuwe werkplek.</p></div>${formButtons('Wijzigingen opslaan')}</form>`);}
case'source-config':{const s=state.sources.find(s=>s.id===m.id);if(s.id==='outlook')return modalShell('Outlook: het koppelplan',`<p>De toekomstige Outlook-connector matcht e-mails met leads via het e-mailadres van het contact, de organisatie en een projectkenmerk.</p><ol><li>De gebruiker geeft zelf toestemming via Microsoft OAuth.</li><li>De connector zoekt binnen de toegestane mailbox en bewaart geheimen op de server.</li><li>Voorgestelde matches worden zichtbaar ter controle; twijfelgevallen vragen een handmatige keuze.</li><li>E-mails en matches blijven bij het eigen bedrijf.</li></ol><span class="badge amber">Nog niet aangesloten · geen toegang tot je mailbox</span>`,btn('Begrepen','close-modal','primary'));return modalShell(`${esc(s.name)} voorbereiden`,`<form id="source-form"><input type="hidden" name="id" value="${s.id}"><label class="field"><span>Bron-URL (voor later)</span><input name="url" type="url" value="${esc(s.url||'')}" placeholder="https://..." maxlength="500"></label><label class="field"><span>Gebruikersnaam (optioneel)</span><input name="username" value="${esc(s.username||'')}" autocomplete="off" maxlength="160"></label><div class="info-box"><strong>Wachtwoord later via een veilige connector</strong><p>Deze bronvoorbereiding maakt geen verbinding. Vul hier geen wachtwoord of toegangstoken in. Echte geheimen worden later alleen op de server versleuteld opgeslagen.</p></div>${formButtons('Voorbereiding opslaan')}</form>`);}

default:return '';}}
function closeModal(){ui.modal=null;renderOverlay();if(lastFocus?.isConnected)lastFocus.focus();}
function openModal(type,id=null,extra={}){lastFocus=document.activeElement;const draft=type==='edit-company'?{logoDraft:companyLogoSource(state.companies.find(c=>c.id===id)),logoDirty:false,logoBusy:false,logoError:''}:{};ui.modal={type,id,...draft,...extra};renderOverlay();}
function renderToasts(){if(!$('#toast-root')||!state)return;const due=callbacks().filter(c=>new Date(c.dueAt)<=Date.now()&&!ui.dismissed.includes(currentUser().id+':'+c.id)).slice(0,2);$('#toast-root').innerHTML=[...transient.map(t=>`<div class="toast ${t.tone}"><span class="toast-icon">${icon(t.tone==='amber'?'clock':'check')}</span><div><strong>${t.tone==='amber'?'Let op':'Opgeslagen'}</strong><p>${esc(t.text)}</p></div><button class="toast-close" data-action="dismiss-toast" data-id="${t.id}" aria-label="Melding sluiten">${icon('close')}</button></div>`),...due.map(c=>`<div class="toast callback-toast"><span class="toast-icon">${icon('bell')}</span><div><strong>Terugbelmoment voor ${esc(userName(c.assigneeId).split(' ')[0])}</strong><button class="text-link" data-action="open-lead" data-id="${c.lead.id}">${esc(c.lead.title)}</button><p>${fmt(c.dueAt)} · Gemaakt door ${esc(c.creatorName)}</p></div><button class="toast-close" data-action="dismiss-callback" data-id="${c.id}" aria-label="Terugbelmelding sluiten">${icon('close')}</button></div>`)].join('');}

document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-action],[data-route]');if(!target||target.disabled)return;
 const a=target.dataset.action,id=target.dataset.id;if(target.matches('.kanban-card')&&Date.now()<suppressCardClickUntil){e.preventDefault();return;}
 if(target.dataset.route){e.preventDefault();if(!state)return;if(['leads','calls','kanban'].includes(target.dataset.route))resetFilters();navTo(target.dataset.route);return;}
 e.preventDefault();
 try{
  if(a==='show-login'){activationToken=null;activation=null;activationInvalid=false;authError='';await initialize();return;}
  if(a==='toggle-password'){const input=document.getElementById(target.getAttribute('aria-controls'));if(!input||!target.closest('.password-field')?.contains(input))return;const visible=input.type==='password';input.type=visible?'text':'password';target.textContent=visible?'Verbergen':'Tonen';target.setAttribute('aria-pressed',String(visible));target.setAttribute('aria-label',document.querySelector(`label[for="${input.id}"]`).textContent+(visible?' verbergen':' tonen'));return;}
  if(!state)return;
  switch(a){
   case'menu':ui.mobile=!ui.mobile;$('.sidebar')?.classList.toggle('open',ui.mobile);break;
   case'open-lead':ui.modal=null;if(ui.drawer!==id)drawerScroll=0;ui.drawer=id;lastFocus=target;renderOverlay();$('#detail-title')?.focus();break;
   case'close-drawer':ui.drawer=null;renderOverlay();if(lastFocus?.isConnected)lastFocus.focus();break;
   case'close-modal':closeModal();break;
   case'demo-info':case'account':case'columns':case'new-company':case'invite':case'source-config':case'edit-user':
    if(['new-company','source-config','edit-user'].includes(a)&&!isChief())throw Error('Deze actie is voor de hoofdbeheerder.');
    if(['columns','invite'].includes(a)&&!canManage())throw Error('Je hebt geen beheerrol.');openModal(a,id);break;
   case'edit-company':{const c=state.companies.find(item=>item.id===id);if(!c||!canManage()||!isChief()&&c.id!==currentUser().companyId)throw Error('Je kunt dit bedrijf niet bewerken.');openModal(a,id);break;}case'remove-company-logo':if(ui.modal?.type==='edit-company'){ui.modal.logoDraft=null;ui.modal.logoDirty=true;ui.modal.logoError='';const fileInput=$('[data-company-logo]');if(fileInput)fileInput.value='';updateCompanyLogoPreview();}break;case'new-lead':openModal(a,null,{status:target.dataset.status});break;
   case'callback':openModal('callback',id);break;
   case'switch-company':await switchCompany(id);break;
   case'reset-filters':resetFilters();render();break;
   case'dash-filter':resetFilters();if(target.dataset.value==='available')ui.availability='available';if(target.dataset.value==='me')ui.owner='me';render();break;
   case'feed-filter':ui.feedFilter=target.dataset.value;render();break;
   case'go-settings':navTo('settings');break;
   case'complete-callback':await mutate('callback.complete',{leadId:target.dataset.leadId,callbackId:id});render();toast('Terugbelafspraak afgehandeld.');break;
   case'register-call':case'call-link':{
    const phone=target.getAttribute('href');target.setAttribute('aria-busy','true');await mutate('call.record',{leadId:id});render();toast('Belmoment geregistreerd.');if(a==='call-link'&&phone?.startsWith('tel:'))location.href=phone;break;
   }
   case'dismiss-toast':transient=transient.filter(t=>t.id!==id);renderToasts();break;
   case'dismiss-callback':ui.dismissed.push(currentUser().id+':'+id);save();renderToasts();break;
   case'rotate-invite':{target.disabled=true;const response=await mutate('invitation.rotate',{invitationId:id});render();showInviteLink(response);break;}
   case'revoke-invite':target.disabled=true;await mutate('invitation.revoke',{invitationId:id});render();toast('Uitnodiging ingetrokken. De link werkt niet meer.');break;
   case'copy-invite':{
    const field=$('#invite-link');field?.focus();field?.select();
    try{await navigator.clipboard.writeText(ui.modal.inviteUrl);toast('Uitnodigingslink gekopieerd. Deel hem met de ontvanger.');}catch{toast('Selecteer de link en kopieer hem met Ctrl+C.','amber');}break;
   }
   case'logout':await mutationQueue;refreshVersion++;await api('/api/auth/logout',{method:'POST',body:{}});session=null;state=null;ui.modal=null;ui.drawer=null;authError='';authRemember=false;transient=[];renderAuth();break;
   case'export':exportLeads();break;
   case'export-report':exportReport();break;
   case'reset-report':Object.assign(ui,{reportCompany:'current',reportSeller:'all',reportSource:'all',reportFrom:'',reportTo:''});render();break;
  }
 }catch(error){if(target.isConnected){target.disabled=false;target.removeAttribute('aria-busy');}if(state)toast(error.message||'De actie is niet gelukt.','amber');else{authError=error.message;renderAuth();}}
});
document.addEventListener('change',async e=>{
 const el=e.target;if(!state)return;
 if(el.hasAttribute('data-company-logo')){
  const m=ui.modal,file=el.files?.[0];if(m?.type!=='edit-company'||!file)return;
  m.logoBusy=true;m.logoError='';updateCompanyLogoPreview();
  try{const logo=await prepareCompanyLogo(file);if(ui.modal===m){m.logoDraft=logo;m.logoDirty=true;}}
  catch(error){if(ui.modal===m)m.logoError=error.message||'Het logo kon niet worden voorbereid.';}
  finally{if(ui.modal===m){m.logoBusy=false;updateCompanyLogoPreview();}}
  return;
 }
 try{
  if(el.dataset.field){const f=el.dataset.field;if(f==='company'){await switchCompany(el.value);return;}else if(f==='available-check')ui.availability=el.checked?'available':'all';else if(f!=='query')ui[f]=el.value;if(f==='reportCompany')ui.reportSeller='all';render();}
  if(el.dataset.work){const field=el.dataset.work;el.disabled=true;await mutate('workspace.update',{leadId:el.dataset.id,field,value:el.type==='checkbox'?el.checked:el.value||null});render();$('[data-work="'+field+'"]')?.focus();}
 }catch(error){if(state){render();toast(error.message,'amber');}}
});
let searchTimer;
document.addEventListener('input',e=>{if(e.target.dataset.field==='query'){const value=e.target.value,pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{ui.query=value;render();const input=$('#lead-search');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}},180);}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));
 if(form.id==='login-form'||form.id==='activation-form'){try{await authenticate(form,data);}catch(error){authError=error.message;renderAuth();}return;}
 if(!state)return;
 const submit=form.querySelector('[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;
 const modalType=ui.modal?.type;
 try{
  let response;
  switch(form.id){
   case'note-form':if(!data.text.trim())throw Error('Schrijf eerst een notitie.');response=await mutate('note.add',{leadId:data.leadId,text:data.text.trim()});break;
   case'lead-form':{
    const oldIds=new Set(state.leads.map(l=>l.id));response=await mutate('lead.create',{...data,status:ui.modal?.status});ui.drawer=response.result?.leadId||response.result?.lead?.id||state.leads.find(l=>!oldIds.has(l.id))?.id||null;break;
   }
   case'callback-form':response=await mutate('callback.add',{leadId:data.leadId,dueAt:amsterdamToISO(data.dueAt),assigneeId:data.assigneeId});break;
   case'columns-form':response=await mutate('columns.update',{columns:company().columns.map(c=>({id:c.id,name:data['col-'+c.id].trim()})),newColumn:data.newColumn.trim()});break;
   case'company-form':response=await mutate('company.create',{name:data.name.trim()});break;case'company-edit-form':{const m=ui.modal;if(m?.logoBusy)throw Error('Wacht tot het logo is voorbereid.');const payload={companyId:data.companyId,name:data.name.trim()};if(m?.logoDirty)payload.logoDataUrl=m.logoDraft;response=await mutate('company.update',payload);break;}
   case'invite-form':response=await mutate('invitation.create',data);break;
   case'user-form':response=await mutate('user.update',data);break;
   case'source-form':response=await mutate('source.update',{id:data.id,url:data.url.trim(),username:data.username.trim()});break;
   case'cooldown-form':response=await mutate('settings.update',{cooldownHours:Number(data.hours)});break;
   default:return;
  }
  ui.modal=null;render();
  if(modalType==='invite')showInviteLink(response);else toast(modalType==='source-config'?'Bronvoorbereiding opgeslagen. Er is geen verbinding gemaakt.':form.id==='note-form'?'Notitie opgeslagen en gedeeld met je bedrijf.':'Je wijziging is opgeslagen.');
 }catch(error){if(submit?.isConnected)submit.disabled=false;if(state)toast(error.message||'Opslaan is niet gelukt.','amber');}
});

// Interpret datetime-local explicitly in Amsterdam, independent of the browser timezone.
function amsterdamToISO(value){const [date,time]=value.split('T'),[y,m,d]=date.split('-').map(Number),[h,minute]=time.split(':').map(Number);const wall=Date.UTC(y,m-1,d,h,minute);let target=wall;for(let i=0;i<3;i++){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(target));const actual=Date.parse(parts.replace(' ','T')+'Z');target+=wall-actual;}const result=new Date(target).toISOString();const verify=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(target)).replace(' ','T');if(verify!==value)throw Error('Dit tijdstip bestaat niet door de overgang naar zomertijd. Kies een ander tijdstip.');return result;}
let dragged=null,suppressCardClickUntil=0;document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-lead]');if(card){suppressCardClickUntil=Infinity;dragged=card.dataset.lead;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';}});document.addEventListener('dragover',e=>{const col=e.target.closest('[data-column]');if(col&&dragged){e.preventDefault();col.dataset.dragOver='true';}});document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-column]');if(col&&!col.contains(e.relatedTarget))delete col.dataset.dragOver;});document.addEventListener('drop',async e=>{const col=e.target.closest('[data-column]');if(!col||!dragged)return;e.preventDefault();const leadId=dragged;suppressCardClickUntil=Date.now()+250;dragged=null;try{await mutate('workspace.update',{leadId,field:'status',value:col.dataset.column});render();}catch(error){if(state){render();toast(error.message,'amber');}}});
document.addEventListener('dragend',()=>{suppressCardClickUntil=Date.now()+250;dragged=null;document.querySelectorAll('[data-drag-over]').forEach(e=>delete e.dataset.dragOver);});
document.addEventListener('keydown',e=>{const card=e.target.closest('.kanban-card[role=button]');if(card&&e.target===card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();card.click();return;}if(e.key==='Escape'){if(ui.modal)closeModal();else if(ui.drawer){ui.drawer=null;renderOverlay();if(lastFocus?.isConnected)lastFocus.focus();}}if(e.key==='Tab'&&(ui.modal||ui.drawer)){const root=$('.modal')||$('.detail-drawer'),items=[...root.querySelectorAll('a[href],button:not([disabled]),input:not([type=hidden]):not([disabled]),select:not([disabled]),textarea')].filter(x=>x.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(routes.some(x=>x[0]===r)&&r!==ui.route){ui.route=r;ui.drawer=null;ui.modal=null;render();}});

function csv(name,rows){const cell=v=>{let value=String(v??'');if(/^[=+\-@\t\r]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Je export is klaargezet als CSV-bestand.');}
function exportLeads(){csv(`bouwberichten-${ui.route==='calls'?'bellijst':'leads'}.csv`,[['Project','Organisatie','Plaats','Bron','Contact','Telefoon','E-mail','Status','Prioriteit','Verkoper','Toezegging','Klaar voor calculatie','Nu belbaar'],...filteredLeads().map(l=>{const w=work(l);return[l.title,l.organization,l.city,names[l.source],l.contact,l.phone,l.email,statusName(w.status),priorityNames[w.priority],userName(w.ownerId),w.commitment?'Ja':'Nee',w.calculation?'Ja':'Nee',eligible(l).allowed?'Ja':'Nee'];})]);}
function exportReport(){const cid=isChief()?(ui.reportCompany==='current'?company().id:ui.reportCompany):company().id;const rows=reportRows(state,{companyId:cid,sellerId:ui.reportSeller,source:ui.reportSource,from:ui.reportFrom,to:ui.reportTo});csv('bouwberichten-conversierapport.csv',[['Bedrijf','Verkoper','Bron','Toegewezen leads','Gebeld','Toezeggingen','Calculaties','Conversie (%)'],...rows.map(r=>[r.companyName,r.sellerName,names[r.source],r.total,r.contacted,r.commitments,r.calculations,Math.round(r.conversion)])]);}
initialize();
setInterval(async()=>{if(!session?.authenticated||pendingMutations||document.hidden)return;try{const editing=!!(ui.modal||ui.drawer||document.activeElement?.matches('input,select,textarea'));await refreshState(ui.companyId,{renderPage:!editing});}catch(error){if(state)toast(error.message,'amber');}},30000);
